#include "reflection/type.h"
#include "util/Sound.h"
#include <boost/signal.hpp>
#include <algorithm>
static double observed_double;
static G3D::Vector3 observed_vector;
static void record_double(double value) { observed_double += value; }
static void record_vector(G3D::Vector3 value) { observed_vector += value; }
int previous_template_checks() {
    int previous = previous_native_checks();
    if (previous) return previous;
    boost::signal1<void, double> doubles;
    boost::signals::connection connection = doubles.connect(&record_double);
    doubles(2.5); connection.disconnect(); doubles(9.0);
    if (observed_double != 2.5) return 101;
    boost::signal1<void, G3D::Vector3> vectors;
    vectors.connect(&record_vector); vectors(G3D::Vector3(1, 2, 3));
    if (observed_vector != G3D::Vector3(1, 2, 3)) return 102;
    int number = 17;
    RBX::Reflection::Value value(number);
    std::vector<RBX::Reflection::Value> values;
    values.push_back(value); values.reserve(32); values.insert(values.begin(), 3, value);
    values.erase(values.begin());
    if (values.size() != 3 || values[2].cast<int>() != 17) return 103;
    values.clear();
    typedef std::pair<unsigned int, boost::shared_ptr<RBX::Instance> > Entry;
    std::vector<Entry> entries;
    entries.push_back(Entry(7, boost::shared_ptr<RBX::Instance>())); entries.reserve(32);
    if (entries[0].first != 7 || entries[0].second) return 104;
    std::map<RBX::Soundscape::SoundId, boost::shared_ptr<RBX::Soundscape::Sound> > sounds;
    RBX::Soundscape::SoundId id("rbxasset://sound.wav");
    sounds[id] = boost::shared_ptr<RBX::Soundscape::Sound>();
    if (sounds.find(id) == sounds.end()) return 105;
    sounds.erase(id); if (!sounds.empty()) return 106;
    std::vector<std::string> words(3, "native");
    if (std::find(words.begin(), words.end(), std::string("native")) != words.begin()) return 107;
    std::printf("template signal/vector/value/cache/find checks passed\n");
    return 0;
}

