    try { invalid.convert<Object>(); } catch(const std::runtime_error& error) { objectRejected=std::strcmp(error.what(),"Unable to cast value to Object")==0; }
    try { invalid.convert<Base>(); } catch(const std::runtime_error& error) { baseRejected=std::strcmp(error.what(),"Unable to cast value to Object")==0; }
    try { invalid.convert<RBX::Lua::FunctionRef>(); } catch(const std::runtime_error& error) { functionRejected=std::strcmp(error.what(),"Unable to cast value to RBX::Lua::FunctionRef")==0; }
    if(!objectRejected || !baseRejected || !functionRejected || invalid.cast<int>()!=17) return 410;
