#include "util/RunningAverage.h"
int previous_average_checks() {
    int previous=previous_value_checks();
    if(previous) return previous;
    RBX::RunningAverageState average;
    G3D::CoordinateFrame identity;
    if(!average.withinTolerance(identity,1.0f,0.00001f)) return 501;
    G3D::CoordinateFrame goal(G3D::Vector3(4,8,12));
    average.update(goal,2.0f);
    if(!average.withinTolerance(G3D::CoordinateFrame(G3D::Vector3(1,2,3)),1.25f,0.00001f)) return 502;
    if(average.withinTolerance(goal,2.0f,0.001f)) return 503;
    G3D::CoordinateFrame rotated(G3D::Matrix3(0,-1,0,1,0,0,0,0,1),G3D::Vector3(-4,7,-12));
    for(int i=0;i<100;++i) average.update(rotated,0.5f);
    if(!average.withinTolerance(rotated,0.5f,0.001f)) return 504;
    if(average.withinTolerance(G3D::CoordinateFrame(rotated.translation),0.5f,0.001f)) return 505;
    if(average.withinTolerance(G3D::CoordinateFrame(rotated.rotation,rotated.translation+G3D::Vector3(-1,0,0)),0.5f,0.001f)) return 506;
    for(int i=0;i<100;++i) average.update(identity,0.0f);
    if(!average.withinTolerance(identity,0.0f,0.001f)) return 507;
    std::printf("native RunningAverage update/tolerance/convergence checks passed\n");
    return 0;
}

